// Some portions generated by Co-Pilot
import { render, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import StatsLayout from "../layout";

vi.mock("next-intl/server", async () => {
  const { createTranslator } =
    await vi.importActual<typeof import("next-intl")>("next-intl");
  const messages = (await import("@/../locales/en.json")).default;
  return {
    getTranslations: async (namespace: "ModernPages.stats") =>
      createTranslator({ locale: "en", messages, namespace }),
  };
});

vi.mock("@/components/Dashboard/Nav", () => ({
  default: () => <nav aria-label="Statistics">Statistics tabs</nav>,
}));

describe("Statistics layout", () => {
  it("shares the same heading and navigation around either tab", async () => {
    const { rerender } = render(
      await StatsLayout({ children: <div>Downloads content</div> }),
    );
    const header = screen.getByRole("heading", {
      level: 1,
      name: "Adoptium download statistics",
    });
    const tabs = screen.getByRole("navigation", { name: "Statistics" });
    rerender(await StatsLayout({ children: <div>Trends content</div> }));
    expect(screen.getByRole("heading", { level: 1 })).toBe(header);
    expect(screen.getByRole("navigation", { name: "Statistics" })).toBe(tabs);
    expect(screen.getByText("Trends content")).toBeInTheDocument();
    expect(screen.queryByText("Downloads content")).not.toBeInTheDocument();
  });
});
